<template>
 <view class="family-page gomoku-page">
  <view class="gomoku-hero"><view><text class="eyebrow">小妙棋社 · 观察与推理</text><text class="title">五子棋小课堂</text><text class="hero-copy">先看懂棋形，再想下一手。</text></view><image src="/static/ui/activities/gomoku.png" mode="aspectFit"/></view>
  <view class="mode-tabs"><button v-for="tab in tabs" :key="tab.id" :class="{active:mode===tab.id}" @click="switchMode(tab.id)">{{ tab.label }}</button></view>
  <text v-if="error" class="error">{{ error }}</text><button v-if="pending" class="secondary save-retry" @click="retrySave">重试保存这次练习</button>
  <view class="rule-note"><text>家庭自由规则</text><text>黑先，轮流下在交叉点；先连成五子或以上获胜，不设禁手。教学小棋盘 9×9，对弈棋盘 15×15。</text></view>
  <template v-if="mode!=='play'">
   <view class="course-heading"><text class="heading">8 个诀窍，一步步学</text><text>{{ summary.independent }} / {{ summary.total }} 题独立完成</text></view>
   <view class="lesson-tabs"><button v-for="(item,i) in lessons" :key="item.id" :class="{active:lessonIndex===i}" @click="selectLesson(i)"><text>{{ String(i+1).padStart(2,'0') }}</text><text>{{ item.title }}</text></button></view>
  </template>
  <view v-if="mode==='play'" class="card game-settings"><view class="setting-row"><text>和谁下？</text><view><button :class="{active:opponent==='bot'}" @click="changeOpponent('bot')">小妙陪练</button><button :class="{active:opponent==='family'}" @click="changeOpponent('family')">同机双人</button></view></view><view v-if="opponent==='bot'" class="setting-row"><text>陪练节奏</text><view><button :class="{active:level==='gentle'}" @click="level='gentle'">入门</button><button :class="{active:level==='thoughtful'}" @click="level='thoughtful'">稳健陪练</button></view></view><text class="muted">{{ opponent==='bot'?'你执黑，小妙执白。留意对方威胁，也寻找自己的机会。':'黑白轮流落子，可以和家长一起说说为什么选这里。' }}</text></view>
  <view class="chess-layout">
   <view class="board-column"><view v-if="mode==='practice'" class="mission-strip"><text>{{ puzzle.title }} · {{ puzzle.toPlay===1?'执黑':'执白' }}</text><text>{{ puzzle.prompt }}</text></view>
    <view class="board-top"><text>{{ boardTitle }}</text><text>{{ boardCaption }}</text></view>
    <view class="board-frame"><view class="column-labels" :style="{gridTemplateColumns:'repeat('+board.length+',1fr)'}"><text v-for="(_,c) in board" :key="c">{{ letters[c] }}</text></view><view class="board-with-rows"><view class="row-labels" :style="{gridTemplateRows:'repeat('+board.length+',1fr)'}"><text v-for="(_,r) in board" :key="r">{{ r+1 }}</text></view><view class="gomoku-board" :style="{gridTemplateColumns:'repeat('+board.length+',minmax(0,1fr))'}" :class="{'is-teaching':mode==='learn'}"><view v-for="(cell,i) in flatBoard" :key="i" :class="['intersection',{firstCol:i%board.length===0,lastCol:i%board.length===board.length-1,firstRow:i<board.length,lastRow:i>=board.length*(board.length-1),preview:isPoint(selected,i),reference:isPoint(reference,i),victory:hasPoint(winLine,i)}]" role="button" :aria-label="cellLabel(i,cell)" @click="selectPoint(Math.floor(i/board.length),i%board.length)"><view v-if="cell" :class="['stone',cell===1?'black':'white']"><view v-if="isPoint(lastMove,i)" class="last-dot"></view></view><view v-else-if="isPoint(selected,i)" :class="['ghost-stone',currentPlayer===1?'dark':'light']"></view><view v-else-if="isPoint(reference,i)" class="reference-dot"></view></view></view></view></view>
    <text class="board-legend">横、竖、两个斜向都要看。红点是最后一手，蓝圈是预选位置。</text>
    <template v-if="mode!=='learn'"><view class="selection-row"><text>{{ selected?'准备下在 '+coordinate(selected):'点一个空位预选，可以换位置再确认' }}</text><view :class="['turn-stone',currentPlayer===1?'black':'white']"></view></view><button v-if="!solved && gameStatus==='playing'" class="primary place" :disabled="!selected||thinking||paused" @click="confirmMove">{{ thinking?'小妙正在观察棋盘…':selected?'确认落子 · '+coordinate(selected):'先选一个交叉点' }}</button><button v-if="mode==='play'&&paused" class="primary place" @click="resumeGame">继续这一盘</button></template>
   </view>
   <view class="teaching-column">
    <view v-if="mode==='learn'" class="card lesson-card"><text class="eyebrow">第 {{ lessonIndex+1 }} 课 · {{ lesson.subtitle }}</text><text class="heading">{{ lesson.title }}</text><text class="body-copy">{{ lesson.observe }}</text><view class="formula"><text>记住这一句</text><text>{{ lesson.formula }}</text></view><text class="body-copy">{{ lesson.explanation }}</text><text class="mistake">容易忽略：{{ lesson.mistake }}</text><button class="primary" @click="startPractice(lesson.puzzleIds[0])">去练这一手 →</button><text class="muted small-note">图中是本课第一道小棋题。学习之后，试着在棋盘上找到落点。</text></view>
    <view v-else-if="mode==='practice'" class="card practice-card"><text class="eyebrow">{{ lesson.title }} · 轮到{{ puzzle.toPlay===1?'黑棋':'白棋' }}</text><text class="heading">{{ puzzle.title }}</text><text class="body-copy">{{ puzzle.prompt }}</text><view class="puzzle-switch"><button v-for="(id,i) in lesson.puzzleIds" :key="id" :class="{active:puzzleId===id}" @click="startPractice(id)">第 {{ i+1 }} 题 {{ progress.independent.includes(id)?'★':progress.practiced.includes(id)?'✓':'◇' }}</button></view><view v-if="feedback" :class="['move-feedback',{success:solved}]"><text>{{ feedback }}</text><text v-if="solved">{{ puzzle.explanation }}</text></view><view v-if="!solved" class="hint-actions"><button class="secondary" @click="showHint">给一点线索</button><button class="link" @click="showReference">看一个参考落点</button></view><text v-if="hintText" class="hint-copy">{{ hintText }}</text><template v-if="solved"><text class="saved-copy">{{ pending?'练习已完成，进度还没保存':usedHelp||hadWrong?'这次练习已记下，理解后可以再独立试一次':'★ 这次独立完成，已保存在本机' }}</text><button class="primary" :disabled="!!pending" @click="nextPuzzle">{{ nextPuzzleLabel }}</button><button class="link" :disabled="!!pending" @click="startPractice(puzzleId)">重新独立挑战本题</button></template><text class="muted small-note">提示后做对也值得肯定。独立星记录每题未借助提示、未试错的一次完成，不重复累计。</text></view>
    <view v-else class="card game-card"><text class="heading">{{ gameHeading }}</text><text class="body-copy">{{ feedback || '先想一想：我能直接成五吗？对方下一手能成五吗？' }}</text><text v-if="lastReason" class="coach-reason">{{ lastReason }}</text><view v-if="gameStatus!=='playing'" class="result-note"><text>{{ gameStatus==='draw'?'棋盘下满了，这盘和棋。':winner===1?'黑棋连成五子！':'白棋连成五子！' }}</text><text>一起复盘：最后的威胁从哪一手开始出现？</text><button class="link" @click="lessonIndex=2;startPractice(lessons[2].puzzleIds[0])">去练“先防成五” →</button></view><view class="game-actions"><button class="secondary" :disabled="!history.length" @click="undo">{{ opponent==='bot'?'退回自己上一手':'悔一手' }}</button><button class="secondary" :disabled="thinking||paused||gameStatus!=='playing'" @click="coachHint">帮我想一想</button></view><button class="link new-game" @click="requestNewGame">重新开一盘</button><button class="link" @click="showHistory=!showHistory">{{ showHistory?'收起棋谱 −':'看看本局落子 ＋' }}</button><view v-if="showHistory" class="move-list"><text v-for="(move,i) in history" :key="i">{{ i+1 }}. {{ move.player===1?'黑':'白' }} {{ coordinate(move) }}</text><text v-if="!history.length">从第一手开始留下棋谱。</text></view></view>
    <view class="card club-note"><text class="heading">学会看棋，比背口诀更重要</text><text class="muted">活四有两个成五点，但仍要先检查对方能否立即获胜。直活三先只学连续三子；跳三和比赛禁手属于后续内容。</text><button class="link" @click="goGrowth">看看我的探索成长 →</button><button class="link" @click="copySource">家长查阅棋形依据 · 复制链接</button></view>
   </view>
  </view>
 </view>
</template>
<script>
import { emptyBoard,placeStone,winningLine,boardFull,chooseGomokuMove,coachMove } from '@/game/gomoku.mjs'
import { lessons,puzzles,puzzleById } from '@/data/gomoku-lessons.mjs'
import { makePuzzleBoard,judgePuzzle,readGomokuLearning,summarizeGomokuLearning } from '@/game/gomoku-learning.mjs'
import { gomokuLearningStore } from '@/services/gomoku-learning.js'
export default {
 data(){return {tabs:[{id:'learn',label:'学诀窍'},{id:'practice',label:'练一手'},{id:'play',label:'下盘棋'}],mode:'learn',lessons,lessonIndex:0,puzzleId:puzzles[0].id,board:makePuzzleBoard(puzzles[0]),letters:'ABCDEFGHIJKLMNO',selected:null,reference:null,lastMove:null,winLine:[],feedback:'',hintText:'',usedHelp:false,hadWrong:false,solved:false,pending:null,progress:readGomokuLearning(''),error:'',opponent:'bot',level:'gentle',turn:1,history:[],winner:0,gameStatus:'playing',thinking:false,paused:false,botTimer:null,lastReason:'',showHistory:false,pageScroll:0}},
 computed:{
 lesson(){return this.lessons[this.lessonIndex]},puzzle(){return puzzleById[this.puzzleId]},flatBoard(){return this.board.flat()},summary(){return summarizeGomokuLearning(this.progress)},currentPlayer(){return this.mode==='play'?this.turn:this.puzzle.toPlay},boardTitle(){return this.mode==='play'?'15×15 · 实战小棋盘':this.mode==='learn'?'看一看这盘棋':'想一想，下在哪里？'},boardCaption(){return this.mode==='play'?this.gameHeading+' · '+this.history.length+' 手':(this.puzzle.toPlay===1?'黑':'白')+'棋先想'},gameHeading(){return this.gameStatus!=='playing'?'这盘棋，一起回看':this.paused?'已暂停，回来再想':this.thinking?'小妙正在想下一手':this.turn===1?'轮到黑棋':'轮到白棋'},nextPuzzleLabel(){const i=this.lesson.puzzleIds.indexOf(this.puzzleId);return i<this.lesson.puzzleIds.length-1?'下一道练习 →':this.lessonIndex<this.lessons.length-1?'下一课 →':'去下盘棋，试试新诀窍 →'}
 },
 onPageScroll(event){this.pageScroll=event.scrollTop},
 onLoad(){this.readProgress()},onHide(){this.stopBot();if(this.mode==='play')this.paused=true},onShow(){this.readProgress()},onUnload(){this.stopBot()},
 onBackPress(){if(!this.pending)return false;uni.showModal({title:'这次练习还没保存',content:'可以留下重试，或放弃本次未保存的进度。',confirmText:'留下重试',cancelText:'放弃离开',success:r=>{if(r.cancel){this.pending=null;uni.navigateBack()}}});return true},
 methods:{
 focusBoard(){this.$nextTick(()=>{uni.createSelectorQuery().in(this).select('.board-column').boundingClientRect(r=>{if(r)uni.pageScrollTo({scrollTop:Math.max(0,this.pageScroll+r.top-16),duration:180})}).exec()})},
 readProgress(){try{this.progress=gomokuLearningStore.read();if(!this.pending)this.error=''}catch(e){this.error=e.message}},coordinate(p){return this.letters[p.col]+(p.row+1)},isPoint(p,i){return !!p&&p.row===Math.floor(i/this.board.length)&&p.col===i%this.board.length},hasPoint(points,i){return points.some(p=>this.isPoint(p,i))},cellLabel(i,cell){return this.coordinate({row:Math.floor(i/this.board.length),col:i%this.board.length})+'，'+(cell===1?'黑棋':cell===2?'白棋':'空位')},
 stopBot(){clearTimeout(this.botTimer);this.botTimer=null;this.thinking=false},clearSelection(){this.selected=null;this.reference=null;this.winLine=[];this.lastMove=null;this.feedback='';this.hintText=''},
 selectLesson(index){if(this.pending){this.error='先保存这次完成的练习，再换一课。';return}this.stopBot();this.lessonIndex=index;this.puzzleId=this.lesson.puzzleIds[0];this.board=makePuzzleBoard(this.puzzle);this.clearSelection();if(this.mode==='practice')this.startPractice(this.puzzleId)},
 switchMode(mode){if(this.mode===mode)return;if(this.pending){this.error='先保存这次完成的练习，再切换。';return}this.stopBot();if(mode==='play'){this.mode='play';this.newGame();this.focusBoard()}else if(mode==='practice')this.startPractice(this.lesson.puzzleIds[0]);else{this.mode='learn';this.puzzleId=this.lesson.puzzleIds[0];this.board=makePuzzleBoard(this.puzzle);this.clearSelection()}},
 startPractice(id){if(this.pending){this.error='先保存这次完成的练习，再继续。';return}const p=puzzleById[id];if(!p)return;this.stopBot();this.mode='practice';this.lessonIndex=this.lessons.findIndex(l=>l.id===p.lessonId);this.puzzleId=id;this.board=makePuzzleBoard(p);this.clearSelection();this.usedHelp=false;this.hadWrong=false;this.solved=false;this.gameStatus='playing';this.paused=false;this.error='';this.focusBoard()},
 selectPoint(row,col){if(this.mode==='learn'||this.solved||this.thinking||this.paused||this.gameStatus!=='playing')return;if(this.mode==='practice')this.board=makePuzzleBoard(this.puzzle);if(this.board[row][col]){this.feedback='这里已经有棋子，换一个空的交叉点试试。';return}this.selected={row,col};this.reference=null},
 confirmMove(){if(!this.selected||this.thinking||this.paused||this.solved||this.gameStatus!=='playing')return;const point={...this.selected};this.selected=null;if(this.mode==='practice'){const result=judgePuzzle(this.puzzle,point.row,point.col);this.board=placeStone(makePuzzleBoard(this.puzzle),point.row,point.col,this.puzzle.toPlay);this.lastMove=point;this.feedback=result.feedback;if(!result.correct){this.hadWrong=true;return}this.solved=true;this.winLine=result.highlights||[];this.pending={id:this.puzzleId,independent:!this.usedHelp&&!this.hadWrong};this.retrySave();return}this.placeGame(point.row,point.col);if(this.gameStatus==='playing'&&this.opponent==='bot'&&this.turn===2)this.scheduleBot()},
 retrySave(){if(!this.pending)return;try{this.progress=gomokuLearningStore.save(this.pending.id,{independent:this.pending.independent});this.pending=null;this.error=''}catch(e){this.error='练习已完成，但进度还没保存：'+e.message}},
 showHint(){if(this.solved)return;this.usedHelp=true;this.hintText=this.puzzle.hint},showReference(){if(this.solved)return;this.usedHelp=true;this.selected=null;const initial=makePuzzleBoard(this.puzzle);for(let row=0;row<initial.length;row++)for(let col=0;col<initial.length;col++){if(!initial[row][col]&&judgePuzzle(this.puzzle,row,col).correct){this.board=initial;this.lastMove=null;this.reference={row,col};this.hintText='参考 '+this.coordinate(this.reference)+'。'+this.puzzle.hint;this.focusBoard();return}}},
 nextPuzzle(){if(!this.solved||this.pending)return;const i=this.lesson.puzzleIds.indexOf(this.puzzleId);if(i<this.lesson.puzzleIds.length-1)this.startPractice(this.lesson.puzzleIds[i+1]);else if(this.lessonIndex<this.lessons.length-1)this.startPractice(this.lessons[this.lessonIndex+1].puzzleIds[0]);else this.switchMode('play')},
 newGame(){this.stopBot();this.board=emptyBoard();this.history=[];this.turn=1;this.winner=0;this.gameStatus='playing';this.paused=false;this.solved=false;this.lastReason='';this.showHistory=false;this.clearSelection()},requestNewGame(){if(!this.history.length||this.gameStatus!=='playing'){this.newGame();return}uni.showModal({title:'重新开一盘？',content:'这盘棋的落子记录会重新开始。',success:r=>{if(r.confirm)this.newGame()}})},changeOpponent(opponent){if(opponent===this.opponent)return;if(!this.history.length||this.gameStatus!=='playing'){this.opponent=opponent;this.newGame();return}uni.showModal({title:'换一个对弈方式？',content:'会重新开始当前棋盘。',success:r=>{if(r.confirm){this.opponent=opponent;this.newGame()}}})},
 placeGame(row,col,reason=''){const player=this.turn;this.board=placeStone(this.board,row,col,player);const point={row,col,player};this.history.push(point);this.lastMove=point;this.selected=null;this.reference=null;this.winLine=winningLine(this.board,row,col);if(reason)this.lastReason='小妙下在 '+this.coordinate(point)+'：'+reason;this.feedback='';if(this.winLine.length){this.winner=player;this.gameStatus='won';this.stopBot()}else if(boardFull(this.board)){this.gameStatus='draw';this.stopBot()}else this.turn=3-player},
 scheduleBot(){this.stopBot();if(this.gameStatus!=='playing'||this.turn!==2||this.opponent!=='bot'||this.paused)return;this.thinking=true;this.botTimer=setTimeout(()=>{this.botTimer=null;try{const p=chooseGomokuMove(this.board,2,{level:this.level});this.thinking=false;if(p)this.placeGame(p.row,p.col,p.reason)}catch(e){this.thinking=false;this.paused=true;this.error='陪练暂时停下了：'+e.message}},280)},resumeGame(){this.paused=false;if(this.turn===2&&this.opponent==='bot')this.scheduleBot()},
 undo(){if(!this.history.length)return;this.stopBot();let count=1;if(this.opponent==='bot'&&this.history[this.history.length-1].player===2)count=2;this.history=this.history.slice(0,Math.max(0,this.history.length-count));this.board=emptyBoard();for(const p of this.history)this.board=placeStone(this.board,p.row,p.col,p.player);this.turn=this.history.length%2===0?1:2;this.gameStatus='playing';this.winner=0;this.paused=false;this.solved=false;this.clearSelection();this.lastMove=this.history[this.history.length-1]||null;this.lastReason='退回这一手后，再看看有没有更早的威胁。'},
 coachHint(){if(this.thinking||this.paused||this.gameStatus!=='playing')return;const p=coachMove(this.board,this.turn);if(!p)return;this.reference={row:p.row,col:p.col};this.selected=null;this.feedback='可以观察 '+this.coordinate(p)+'。'+p.reason},goGrowth(){uni.navigateTo({url:'/pages/growth/learning'})},copySource(){uni.setClipboardData({data:'https://www.renju.net/rules/'})}
 }
}
</script>
<style src="@/styles/family.css"></style>
<style scoped>
