y:grid;width:22px;flex-shrink:0;color:#9c7c50;font-size:9px;text-align:center}.row-labels text{display:flex;align-items:center;justify-content:center;flex:1}.gomoku-board{display:grid;flex:1;min-width:0;aspect-ratio:1;touch-action:manipulation;user-select:none}.intersection{position:relative;min-width:0;aspect-ratio:1;cursor:pointer}.intersection::before,.intersection::after{content:'';position:absolute;background:#b68d56;pointer-events:none}.intersection::before{left:0;top:50%;width:100%;height:1px}.intersection::after{left:50%;top:0;height:100%;width:1px}.intersection.firstCol::before{left:50%;width:50%}.intersection.lastCol::before{width:50%}.intersection.firstRow::after{top:50%;height:50%}.intersection.lastRow::after{height:50%}.stone,.ghost-stone{position:absolute;z-index:1;width:80%;height:80%;left:10%;top:10%;border-radius:50%;box-sizing:border-box}.black,.ghost-stone.dark{background:radial-gradient(circle at 30% 25%,#5c6670,#202a31 55%,#101b20);box-shadow:1px 2px 3px #4d3b334d}.white,.ghost-stone.light{background:radial-gradient(circle at 30% 25%,#fff,#f7f6ec 60%,#d6d6ca);border:1px solid #9b9f9670;box-shadow:1px 2px 3px #4d3b3333}.ghost-stone{opacity:.5}.intersection.preview{box-shadow:inset 0 0 0 2px #377fa7;border-radius:50%}.intersection.victory .stone{box-shadow:0 0 0 3px #dfad43}.last-dot{position:absolute;width:17%;height:17%;background:#d39173;border-radius:50%;left:41.5%;top:41.5%}.reference-dot{position:absolute;width:36%;height:36%;left:32%;top:32%;border-radius:50%;border:2px solid #2d917c;background:#e4f4ee;z-index:2;box-sizing:border-box}.board-legend{display:block;font-size:11px;color:#7f8d80;line-height:1.8;margin:12px 2px}.selection-row{display:flex;align-items:center;justify-content:space-between;gap:12px;font-size:12px;color:#567569;margin:14px 0 10px}.turn-stone{height:20px;width:20px;border-radius:50%;flex-shrink:0}.place{width:100%;margin:0 0 18px;background:#2f7866!important;border-color:#276955!important}.body-copy{display:block;font-